<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/banking_connections.php';require_once dirname(__DIR__).'/private/ui.php';
$admin=(int)$_SESSION['admin_id'];$ready=bankingReady($pdo);$setup=bankingSetupStatus($config);$slot=(string)($_GET['slot']??'sparkasse');if(!isset(GSZ_BANK_SLOTS[$slot]))$slot='sparkasse';$back='bank_connections.php?slot='.$slot;
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{if(!$ready)throw new RuntimeException('Datenbankeinrichtung370 erforderlich.');$action=(string)($_POST['action']??'');
 if($action==='disconnect'){if(empty($_POST['confirm']))throw new RuntimeException('Lokales Trennen bestätigen.');bankingDisconnect($pdo,$admin,$slot);$_SESSION['app_notice']='Lokale Verbindung getrennt; Umsätze erhalten. Eine noch bestehende Bank-/Providerfreigabe zusätzlich dort widerrufen.';}
 elseif($action==='business_account'){$name='Geschäftskonto Sparkasse';$pdo->prepare('INSERT INTO bank_accounts(name) VALUES(?) ON DUPLICATE KEY UPDATE name=VALUES(name)')->execute([$name]);$_SESSION['app_notice']='Internes Geschäftskonto vorbereitet. Noch keine Bank verbunden.';}
 else{$client=new GszEnableBankingClient($config);$allowCreate=$action==='authorize'&&(int)$pdo->query("SELECT COUNT(*) FROM bank_connections WHERE payload<>'{}'")->fetchColumn()===0;$key=$action==='institutions'?'':bankingKey(null,$allowCreate);if($action==='institutions'){$list=$client->institutions();$_SESSION['bank_institutions']=$list;$_SESSION['app_notice']='Tatsächliche Anbieterliste geladen. Kontotyp und Bankunterstützung bewusst prüfen.';}
 elseif($action==='authorize'){if(empty($_POST['confirm']))throw new RuntimeException('Lesenden Zugriff und geprüfte Anbieterbedingungen bestätigen.');$name=(string)($_POST['institution']??'');$type=(string)($_POST['psu_type']??'');$allowed=false;foreach($_SESSION['bank_institutions']??[] as $bank)if($bank['name']===$name&&in_array($type,$bank['psu_types'],true))$allowed=true;if(!$allowed)throw new RuntimeException('Bank/Kontotyp fehlt in der tatsächlich geladenen Anbieterliste.');$url=bankingStart($pdo,$admin,$slot,$name,$type,$client,$key);header('Location: '.$url,true,303);exit;}
 elseif($action==='exchange'){bankingExchange($pdo,$admin,$slot,$client,$key);$_SESSION['app_notice']='Bankfreigabe erhalten. Jetzt ausschließlich das richtige Konto zuordnen.';}
 elseif($action==='bind'){if(empty($_POST['confirm']))throw new RuntimeException('Kontozuordnung ausdrücklich bestätigen.');bankingBind($pdo,$admin,$slot,(string)($_POST['account_uid']??''),(int)($_POST['business_account_id']??0),$key);$_SESSION['app_notice']='Lesende Kontoverbindung gespeichert. Noch keine Umsätze automatisch gebucht.';}
 elseif($action==='refresh'||$action==='refresh_all'){$slots=$action==='refresh_all'?array_keys(GSZ_BANK_SLOTS):[$slot];$messages=[];foreach($slots as $s){$c=bankingGet($pdo,$s,$admin);if(!$c||$c['status']!=='connected'){$messages[]=GSZ_BANK_SLOTS[$s].': nicht verbunden';continue;}try{$result=bankingRefresh($pdo,$admin,$s,(string)($_POST['from']??''),(string)($_POST['to']??''),$client,$key);$messages[]=GSZ_BANK_SLOTS[$s].': '.($result['review_required']?'Importvorschlag zur Prüfung':'Abruf verarbeitet').' ('.$result['rows'].' Quellzeilen)';}catch(Throwable $e){$messages[]=GSZ_BANK_SLOTS[$s].': Abruf fehlgeschlagen; Daten erhalten';}}$_SESSION['app_notice']=implode(' · ',$messages);}
 else throw new RuntimeException('Aktion unbekannt.');}
 }catch(Throwable $e){$_SESSION['app_error']=$e instanceof PDOException?'Bankeinrichtung nicht bereit. Migration und Kontozuordnung prüfen.':$e->getMessage();}redirect($back);}
$connections=[];$business=[];if($ready){$q=$pdo->prepare('SELECT * FROM bank_connections WHERE admin_id=? ORDER BY slot');$q->execute([$admin]);$connections=array_column($q->fetchAll(),null,'slot');$business=$pdo->query('SELECT id,name FROM bank_accounts ORDER BY id')->fetchAll();}$current=$connections[$slot]??null;$data=[];if($current&&in_array($current['status'],['choose_account','connected'],true)){try{$data=bankingOpen($current['payload'],bankingKey());}catch(Throwable $e){$_SESSION['app_error']='Banktokens nicht lesbar. Schlüssel/Sicherung prüfen, keine neue Verbindung vortäuschen.';}}
$liveConnected=$current&&$current['status']==='connected'&&strtotime($current['consent_until'].' UTC')>time();$connectionLabel=$current&&$current['status']==='connected'&&!$liveConnected?'Freigabe abgelaufen – neu verbinden':($current&&$current['status']==='connected'&&!$setup['ready']?'Verbindung gespeichert – Onlineabruf deaktiviert':null);$labels=['not_connected'=>'Nicht verbunden','pending'=>'Bankfreigabe ausstehend','awaiting_owner'=>'Bankrückmeldung empfangen – Bestätigung erforderlich','choose_account'=>'Freigegebenes Konto auswählen','connected'=>'Lesend verbunden'];gszPageStart('Bankverbindungen');
?><p>Ein Geschäftskonto und zwei getrennte Immobilienkonten. Keine PIN/TAN in der Zentrale; Anmeldung und Freigaben erfolgen ausschließlich beim autorisierten Anbieter beziehungsweise der Bank. Keine Überweisungsfunktion. CSV/CAMT bleiben unter <a href="bank.php">Geschäftsbank</a> und <a href="estate_bank.php">Immobilienbank</a> verfügbar.</p><p><strong><?=e($setup['status'])?></strong></p><?php if(!$setup['ready']):?><p>Onlinezugriff ist gesperrt, solange Anbieterzugang, tatsächliche Bankunterstützung, Kosten-/Vertragsfreigabe oder private Signaturkonfiguration fehlen. Ein kostenloser Zugang für diese drei konkreten Konten wurde nicht nachgewiesen. Siehe BANKING-ANBINDUNG.md. Kein kostenpflichtiger Dienst aktiviert.</p><?php endif?>
<?php if(!$ready):?><p class="error">Einrichtungsassistent und Migration370 zuerst abschließen.</p><?php else:?><nav class="actions"><?php foreach(GSZ_BANK_SLOTS as $s=>$title):?><a href="?slot=<?=e($s)?>"><?=e($title)?></a><?php endforeach?></nav><section class="card"><h2><?=e(GSZ_BANK_SLOTS[$slot])?></h2><p>Status: <strong><?=e($connectionLabel??$labels[$current['status']??'not_connected']??'Nicht verbunden')?></strong></p><?php if($current):?><p>Bank: <?=e($current['institution'])?> · Freigabe bis <?=e($current['consent_until']??'noch keine')?> UTC</p><p>Letzter Abrufversuch <?=e($current['last_attempt_at']??'noch keiner')?> UTC · Letzter erfolgreicher Abruf <?=e($current['last_success_at']??'noch keiner')?> UTC</p><?php if($current['last_error_code']):?><p class="error">Abruf fehlgeschlagen. Quelle/Freigabe prüfen; bisherige Daten bleiben erhalten.</p><?php endif;if($current['balance_cents']!==null):?><p>Vom Anbieter gelieferter gebuchter Saldo: <?=e(financeDecimal((int)$current['balance_cents']))?> EUR · Typ <?=e($current['balance_type'])?> · Abrufstand <?=e($current['balance_at'])?> UTC. Kein Echtzeitversprechen.</p><?php endif;endif?>
